import { readdir, readFile, writeFile } from 'node:fs/promises';

const migrations = new URL('../supabase/migrations/', import.meta.url);
const names = (await readdir(migrations)).filter(name => name.endsWith('.sql')).sort();
const sections = await Promise.all(names.map(async name =>
  `-- Migration: ${name}\n${await readFile(new URL(name, migrations), 'utf8')}`
));
await writeFile(new URL('../supabase/setup.sql', import.meta.url),
  '-- Generated by scripts/generate-supabase-setup.mjs. Edit the source migrations.\n' +
  '-- Run in the SQL Editor of the Supabase project connected to this app.\n' +
  '-- Creates application tables and restores missing profiles as Viewers.\n' +
  '-- Existing profile roles and account statuses are preserved.\n\nBEGIN;\n\n' +
  sections.join('\n\n') + "\n\nNOTIFY pgrst, 'reload schema';\nCOMMIT;\n"
);
console.log(`Prepared setup SQL from ${names.length} migrations.`);
